def seed():
    app = create_app()
    with app.app_context():
        init_db()
        db = get_db()

        db.execute('DELETE FROM lesson_progress')
        db.execute('DELETE FROM lessons')
        db.execute('DELETE FROM topics')
        db.commit()

        total_lessons = 0
        for item in TOPICS:
            t = item['topic']
            cur = db.execute(
                'INSERT INTO topics (name, description, difficulty, icon, order_index) VALUES (?, ?, ?, ?, ?)',
                (t['name'], t['description'], t['difficulty'], t['icon'], t['order_index']),
            )
            topic_id = cur.lastrowid

            for idx, lesson in enumerate(item['lessons']):
                db.execute(
                    '''INSERT INTO lessons
                       (topic_id, title, explanation, real_world, commands, code_example,
                        quiz_question, quiz_answer, difficulty, estimated_minutes, tags, order_index)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                    (
                        topic_id,
                        lesson['title'],
                        lesson['explanation'],
                        lesson['real_world'],
                        lesson['commands'],
                        lesson['code_example'],
                        lesson['quiz_question'],
                        lesson['quiz_answer'],
                        lesson.get('difficulty', 'beginner'),
                        lesson.get('estimated_minutes', 10),
                        lesson.get('tags', ''),
                        idx + 1,
                    ),
                )
                total_lessons += 1

        db.commit()
        print(f'Seeded {len(TOPICS)} topics and {total_lessons} lessons.')


if __name__ == '__main__':
    seed()
